{
  "category_edits": [
    {
      "category": "embedding_representation",
      "rationale": "Normalize input item embeddings by RMS magnitude with epsilon 1e-6 before dropout to stabilize recurrent inputs. Padding remains zero. Dimensions, output embeddings, GRU topology, scoring, loss and optimizer remain unchanged. The generated predictor imports this same model class, so inference uses identical normalization.",
      "edits": [
        {
          "find": "    def encode(self, seq: torch.Tensor) -> torch.Tensor:\n        emb = self.dropout(self.item_emb(seq))",
          "replace": "    def encode(self, seq: torch.Tensor) -> torch.Tensor:\n        emb = self.item_emb(seq)\n        emb = emb * torch.rsqrt(emb.square().mean(dim=-1, keepdim=True) + 1e-6)\n        emb = self.dropout(emb)"
        },
        {
          "find": "    def forward(self, seq: torch.Tensor, pos: torch.Tensor, neg: torch.Tensor):\n        emb = self.dropout(self.item_emb(seq))",
          "replace": "    def forward(self, seq: torch.Tensor, pos: torch.Tensor, neg: torch.Tensor):\n        emb = self.item_emb(seq)\n        emb = emb * torch.rsqrt(emb.square().mean(dim=-1, keepdim=True) + 1e-6)\n        emb = self.dropout(emb)"
        }
      ]
    }
  ],
  "change_summary": "Apply parameter-free RMS normalization to input embeddings during training and inference for all four category models."
}
